// Pure helpers for the Oriel design-token generator.
// build.mjs writes the platform files with these; tokens.test.mjs checks the palette with them.

const HEADER =
  'Generated by shared/design-tokens/build.mjs from shared/design-tokens/tokens.json. Do not edit by hand.';

// ---------- Color math ----------

export function parseColor(input) {
  const value = String(input).trim();
  let match = /^#([0-9a-f]{6})([0-9a-f]{2})?$/i.exec(value);
  if (match) {
    const n = parseInt(match[1], 16);
    return {
      r: (n >> 16) & 255,
      g: (n >> 8) & 255,
      b: n & 255,
      a: match[2] ? parseInt(match[2], 16) / 255 : 1,
    };
  }
  match = /^rgba?\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\s*(?:,\s*(0|1|0?\.\d+))?\s*\)$/i.exec(value);
  if (match) {
    const [r, g, b] = [match[1], match[2], match[3]].map(Number);
    if ([r, g, b].some((c) => c > 255)) throw new Error(`Color channel out of range: ${input}`);
    return { r, g, b, a: match[4] === undefined ? 1 : Number(match[4]) };
  }
  throw new Error(`Unsupported color: ${input}`);
}

export function toArgbHex({ r, g, b, a }) {
  return [Math.round(a * 255), r, g, b]
    .map((n) => Math.round(n).toString(16).padStart(2, '0').toUpperCase())
    .join('');
}

/** Paints `top` (which may be translucent) over an opaque `bottom`. */
export function composite(top, bottom) {
  const mix = (t, b) => t * top.a + b * (1 - top.a);
  return { r: mix(top.r, bottom.r), g: mix(top.g, bottom.g), b: mix(top.b, bottom.b), a: 1 };
}

function linear(channel) {
  const s = channel / 255;
  return s <= 0.04045 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
}

/** WCAG relative luminance of an opaque color. */
export function luminance({ r, g, b }) {
  return 0.2126 * linear(r) + 0.7152 * linear(g) + 0.0722 * linear(b);
}

/** WCAG contrast ratio between two opaque colors. */
export function contrastRatio(a, b) {
  const [high, low] = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (high + 0.05) / (low + 0.05);
}

// ---------- Naming ----------

const kebab = (name) => name.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase();
const pascal = (name) => name.charAt(0).toUpperCase() + name.slice(1);
const trim = (n) => Number(n.toFixed(4)).toString();

// ---------- CSS ----------

function block(selector, entries) {
  const body = entries.map(([name, value]) => `  ${name}: ${value};`).join('\n');
  return `${selector} {\n${body}\n}`;
}

function media(query, selector, entries) {
  const inner = block(selector, entries)
    .split('\n')
    .map((line) => `  ${line}`)
    .join('\n');
  return `@media ${query} {\n${inner}\n}`;
}

/** Layers each glow as an ellipse that fades to its own color at zero alpha, over the base color. */
function cssWallpaper({ base, glows }) {
  const layers = glows.map(({ color, x, y, radius }) => {
    const { r, g, b } = parseColor(color);
    const size = `${trim(radius * 100)}%`;
    return `radial-gradient(${size} ${size} at ${trim(x * 100)}% ${trim(y * 100)}%, ${color} 0%, rgba(${r}, ${g}, ${b}, 0) 100%)`;
  });
  return [...layers, base].join(', ');
}

function themeEntries(tokens, theme) {
  const entries = [['color-scheme', theme]];
  for (const [name, value] of Object.entries(tokens.color[theme])) {
    entries.push([`--o-raw-color-${kebab(name)}`, value]);
  }
  entries.push(['--o-raw-color-accent', `var(--o-accent-on-${theme})`]);
  for (const [name, value] of Object.entries(tokens.glass[theme])) {
    entries.push([`--o-raw-glass-${kebab(name)}`, value]);
  }
  for (const [name, value] of Object.entries(tokens.material[theme])) {
    entries.push([`--o-raw-material-${kebab(name)}`, value]);
  }
  for (const [level, value] of Object.entries(tokens.elevation[theme])) {
    entries.push([`--o-elevation-${level}`, value]);
  }
  return entries;
}

export function renderCss(tokens) {
  const base = [];
  for (const [name, value] of Object.entries(tokens.radius)) base.push([`--o-radius-${name}`, `${value}px`]);
  for (const [name, value] of Object.entries(tokens.space)) base.push([`--o-space-${name}`, `${value}px`]);
  for (const [name, value] of Object.entries(tokens.blur)) base.push([`--o-blur-${name}`, `${value}px`]);
  for (const [name, value] of Object.entries(tokens.material.blur)) {
    base.push([`--o-material-blur-${kebab(name)}`, `${value}px`]);
  }
  for (const [name, value] of Object.entries(tokens.saturation)) base.push([`--o-saturate-${name}`, String(value)]);
  for (const [name, value] of Object.entries(tokens.motion.duration)) base.push([`--o-duration-${name}`, `${value}ms`]);
  for (const [name, points] of Object.entries(tokens.motion.easing)) {
    base.push([`--o-ease-${name}`, `cubic-bezier(${points.join(', ')})`]);
  }
  base.push(['--o-focus-scale', String(tokens.focus.scale)]);
  base.push(['--o-focus-ring-width', `${tokens.focus.ringWidth}px`]);
  base.push(['--o-focus-ring-offset', `${tokens.focus.ringOffset}px`]);
  for (const [name, value] of Object.entries(tokens.type.fontFamily)) base.push([`--o-font-${name}`, value]);
  for (const [name, style] of Object.entries(tokens.type.web)) {
    const prefix = `--o-text-${kebab(name)}`;
    base.push([`${prefix}-size`, `${trim(style.size / 16)}rem`]);
    base.push([`${prefix}-line`, String(style.lineHeight)]);
    base.push([`${prefix}-weight`, String(style.weight)]);
    base.push([`${prefix}-tracking`, `${style.tracking}em`]);
  }
  for (const [id, accent] of Object.entries(tokens.accent.options)) {
    base.push([`--o-accent-${id}-dark`, accent.dark]);
    base.push([`--o-accent-${id}-light`, accent.light]);
  }
  base.push(['--o-accent-on-dark', `var(--o-accent-${tokens.accent.default}-dark)`]);
  base.push(['--o-accent-on-light', `var(--o-accent-${tokens.accent.default}-light)`]);
  for (const [id, wallpaper] of Object.entries(tokens.wallpaper.options)) {
    base.push([`--o-wallpaper-${id}`, cssWallpaper(wallpaper)]);
  }
  base.push(['--o-wallpaper-default', `var(--o-wallpaper-${tokens.wallpaper.default})`]);

  const accents = Object.keys(tokens.accent.options).map((id) =>
    block(`:root[data-accent="${id}"]`, [
      ['--o-accent-on-dark', `var(--o-accent-${id}-dark)`],
      ['--o-accent-on-light', `var(--o-accent-${id}-light)`],
    ]),
  );

  const dark = themeEntries(tokens, 'dark');
  const light = themeEntries(tokens, 'light');

  const colorNames = [...Object.keys(tokens.color.dark), 'accent'];
  const glassNames = Object.keys(tokens.glass.dark);
  const materialNames = Object.keys(tokens.material.dark);
  const publicNames = [
    ...colorNames.map((name) => [`--o-color-${kebab(name)}`, `var(--o-raw-color-${kebab(name)})`]),
    ...glassNames.map((name) => [`--o-glass-${kebab(name)}`, `var(--o-raw-glass-${kebab(name)})`]),
    ...materialNames.map((name) => [`--o-material-${kebab(name)}`, `var(--o-raw-material-${kebab(name)})`]),
  ];

  // Reduced transparency turns every glass surface and material solid, and stops all blur.
  const solidGlass = [
    ['--o-glass-regular', 'var(--o-glass-solid)'],
    ['--o-glass-clear', 'var(--o-glass-solid)'],
    ['--o-blur-regular', '0px'],
    ['--o-blur-clear', '0px'],
    ...materialNames.flatMap((name) => [
      [`--o-material-${kebab(name)}`, 'var(--o-glass-solid)'],
      [`--o-material-blur-${kebab(name)}`, '0px'],
    ]),
  ];
  const moreContrast = [
    ...solidGlass,
    ['--o-glass-edge', 'var(--o-raw-color-text-tertiary)'],
    ['--o-color-text-secondary', 'var(--o-raw-color-text-primary)'],
    ['--o-color-text-tertiary', 'var(--o-raw-color-text-secondary)'],
    ['--o-color-border', 'var(--o-raw-color-text-tertiary)'],
  ];
  const lessMotion = [
    ...Object.keys(tokens.motion.duration).map((name) => [`--o-duration-${name}`, '0ms']),
    ['--o-focus-scale', '1'],
  ];

  // A scope re-declares the public names so a subtree, such as the launcher demo, can preview another theme.
  // OS accessibility settings still win inside a scope; the data-attribute overrides come last.
  const scope = '[data-oriel-scope]';
  const scoped = [
    `/* Scoped previews: <div data-oriel-scope data-theme="light" data-accent="amber">. */`,
    ...Object.keys(tokens.accent.options).map((id) =>
      block(`${scope}[data-accent="${id}"]`, [
        ['--o-accent-on-dark', `var(--o-accent-${id}-dark)`],
        ['--o-accent-on-light', `var(--o-accent-${id}-light)`],
      ]),
    ),
    block(`${scope}[data-theme="dark"]`, [...dark, ...publicNames]),
    block(`${scope}[data-theme="light"]`, [...light, ...publicNames]),
    media('(prefers-reduced-transparency: reduce)', `${scope}[data-theme]`, solidGlass),
    media('(prefers-contrast: more)', `${scope}[data-theme]`, moreContrast),
    block(`${scope}[data-transparency="reduced"]`, solidGlass),
    block(`${scope}[data-motion="reduced"]`, lessMotion),
  ];

  return [
    `/* ${HEADER} */`,
    block(':root', base),
    ...accents,
    '/* Themes. Dark is the default; light follows the system unless a theme is chosen. */',
    block(':root,\n:root[data-theme="dark"]', dark),
    media('(prefers-color-scheme: light)', ':root:not([data-theme="dark"])', light),
    block(':root[data-theme="light"]', light),
    '/* Public names. Components use these; the overrides below can redirect them. */',
    block(':root', publicNames),
    '/* Accessibility overrides: system settings, or the matching data attribute on <html>. */',
    media('(prefers-reduced-transparency: reduce)', ':root', solidGlass),
    block(':root[data-transparency="reduced"]', solidGlass),
    media('(prefers-contrast: more)', ':root', moreContrast),
    block(':root[data-contrast="more"]', moreContrast),
    media('(prefers-reduced-motion: reduce)', ':root', lessMotion),
    block(':root[data-motion="reduced"]', lessMotion),
    ...scoped,
    '',
  ].join('\n\n');
}

// ---------- TypeScript (website) ----------

export function renderTs(tokens) {
  const accents = Object.entries(tokens.accent.options).map(([id, accent]) => ({
    id,
    label: accent.label,
    dark: accent.dark,
    light: accent.light,
  }));
  const wallpapers = Object.entries(tokens.wallpaper.options).map(([id, wallpaper]) => ({
    id,
    label: wallpaper.label,
    tone: wallpaper.tone,
  }));
  return [
    `// ${HEADER}`,
    '',
    `export const accents = ${JSON.stringify(accents, null, 2)} as const;`,
    '',
    'export type AccentId = (typeof accents)[number]["id"];',
    '',
    `export const defaultAccent: AccentId = ${JSON.stringify(tokens.accent.default)};`,
    '',
    `export const wallpapers = ${JSON.stringify(wallpapers, null, 2)} as const;`,
    '',
    'export type WallpaperId = (typeof wallpapers)[number]["id"];',
    '',
    `export const defaultWallpaper: WallpaperId = ${JSON.stringify(tokens.wallpaper.default)};`,
    '',
    `export const themePacks = ${JSON.stringify(
      Object.entries(tokens.themePack.options).map(([id, pack]) => ({ id, ...pack })),
      null,
      2,
    )} as const;`,
    '',
    'export type ThemePackId = (typeof themePacks)[number]["id"];',
    '',
  ].join('\n');
}

// ---------- Kotlin ----------

const kotlinColor = (value) => `Color(0x${toArgbHex(parseColor(value))})`;
const kotlinFloat = (n) => `${Number.isInteger(n) ? n : trim(n)}f`;
const kotlinNumber = (n) => (n < 0 ? `(${n})` : String(n));

function kotlinObject(name, lines, indent) {
  const pad = ' '.repeat(indent);
  return [`${pad}object ${name} {`, ...lines.map((line) => `${pad}    ${line}`), `${pad}}`];
}

export function renderKotlin(tokens, packageName = 'tv.oriel.launcher.ui.theme') {
  const colorLines = (palette) =>
    Object.entries(palette).map(([name, value]) => `val ${pascal(name)} = ${kotlinColor(value)}`);

  const accentIds = Object.keys(tokens.accent.options);
  const accentLines = [
    ...accentIds.map((id) => {
      const accent = tokens.accent.options[id];
      return (
        `val ${pascal(id)} = AccentToken(id = "${id}", label = "${accent.label}", ` +
        `onDark = ${kotlinColor(accent.dark)}, onLight = ${kotlinColor(accent.light)})`
      );
    }),
    `val All: List<AccentToken> = listOf(${accentIds.map(pascal).join(', ')})`,
    `val Default: AccentToken = ${pascal(tokens.accent.default)}`,
  ];

  const wallpaperIds = Object.keys(tokens.wallpaper.options);
  const wallpaperLines = [
    ...wallpaperIds.flatMap((id) => {
      const wallpaper = tokens.wallpaper.options[id];
      const glows = wallpaper.glows.map(
        ({ color, x, y, radius }) =>
          `    WallpaperGlow(color = ${kotlinColor(color)}, x = ${kotlinFloat(x)}, y = ${kotlinFloat(y)}, radius = ${kotlinFloat(radius)}),`,
      );
      return [
        `val ${pascal(id)} = WallpaperToken(`,
        `    id = "${id}",`,
        `    label = "${wallpaper.label}",`,
        `    isLight = ${wallpaper.tone === 'light'},`,
        `    base = ${kotlinColor(wallpaper.base)},`,
        '    glows = listOf(',
        ...glows.map((line) => `    ${line}`),
        '    ),',
        ')',
      ];
    }),
    `val All: List<WallpaperToken> = listOf(${wallpaperIds.map(pascal).join(', ')})`,
    `val Default: WallpaperToken = ${pascal(tokens.wallpaper.default)}`,
  ];

  const packIds = Object.keys(tokens.themePack.options);
  const packLines = [
    ...packIds.map((id) => {
      const pack = tokens.themePack.options[id];
      return (
        `val ${pascal(id)} = ThemePackToken(id = "${id}", label = "${pack.label}", description = "${pack.description}", ` +
        `isLight = ${pack.theme === 'light'}, accentId = "${pack.accent}", wallpaperId = "${pack.wallpaper}")`
      );
    }),
    `val All: List<ThemePackToken> = listOf(${packIds.map(pascal).join(', ')})`,
  ];

  const typeLines = Object.entries(tokens.type.tv).flatMap(([name, style]) =>
    kotlinObject(
      pascal(name),
      [
        `val Size = ${style.size}.sp`,
        `val LineHeight = ${style.lineHeight}.sp`,
        `const val Weight = ${style.weight}`,
        `val Tracking = ${kotlinNumber(style.tracking)}.sp`,
      ],
      0,
    ),
  );

  const body = [
    ...kotlinObject('DarkColor', colorLines(tokens.color.dark), 4),
    '',
    ...kotlinObject('LightColor', colorLines(tokens.color.light), 4),
    '',
    ...kotlinObject('DarkGlass', colorLines(tokens.glass.dark), 4),
    '',
    ...kotlinObject('LightGlass', colorLines(tokens.glass.light), 4),
    '',
    ...kotlinObject('DarkMaterial', colorLines(tokens.material.dark), 4),
    '',
    ...kotlinObject('LightMaterial', colorLines(tokens.material.light), 4),
    '',
    ...kotlinObject(
      'MaterialBlur',
      Object.entries(tokens.material.blur).map(([name, value]) => `val ${pascal(name)} = ${value}.dp`),
      4,
    ),
    '',
    ...kotlinObject('Accent', accentLines, 4),
    '',
    ...kotlinObject('Wallpaper', wallpaperLines, 4),
    '',
    ...kotlinObject('ThemePack', packLines, 4),
    '',
    ...kotlinObject(
      'Blur',
      Object.entries(tokens.blur).map(([name, value]) => `val ${pascal(name)} = ${value}.dp`),
      4,
    ),
    '',
    ...kotlinObject(
      'Saturation',
      Object.entries(tokens.saturation).map(([name, value]) => `const val ${pascal(name)} = ${kotlinFloat(value)}`),
      4,
    ),
    '',
    ...kotlinObject(
      'Radius',
      Object.entries(tokens.radius).map(([name, value]) => `val ${pascal(name)} = ${value}.dp`),
      4,
    ),
    '',
    ...kotlinObject(
      'Space',
      Object.entries(tokens.space).map(([name, value]) => `val S${name} = ${value}.dp`),
      4,
    ),
    '',
    ...kotlinObject(
      'Duration',
      Object.entries(tokens.motion.duration).map(([name, value]) => `const val ${pascal(name)} = ${value}`),
      4,
    ),
    '',
    ...kotlinObject(
      'Easing',
      Object.entries(tokens.motion.easing).map(
        ([name, points]) => `val ${pascal(name)} = CubicBezierEasing(${points.map(kotlinFloat).join(', ')})`,
      ),
      4,
    ),
    '',
    ...kotlinObject(
      'Focus',
      [
        `const val Scale = ${kotlinFloat(tokens.focus.scale)}`,
        `val RingWidth = ${tokens.focus.ringWidth}.dp`,
        `val RingOffset = ${tokens.focus.ringOffset}.dp`,
      ],
      4,
    ),
    '',
    ...kotlinObject('TvType', typeLines, 4),
  ];

  return [
    `// ${HEADER}`,
    '',
    `package ${packageName}`,
    '',
    'import androidx.compose.animation.core.CubicBezierEasing',
    'import androidx.compose.ui.graphics.Color',
    'import androidx.compose.ui.unit.dp',
    'import androidx.compose.ui.unit.sp',
    '',
    'object OrielTokens {',
    ...body,
    '}',
    '',
    'data class AccentToken(val id: String, val label: String, val onDark: Color, val onLight: Color)',
    '',
    '/** A radial glow. Position and radius are fractions of the screen size. */',
    'data class WallpaperGlow(val color: Color, val x: Float, val y: Float, val radius: Float)',
    '',
    'data class WallpaperToken(',
    '    val id: String,',
    '    val label: String,',
    '    val isLight: Boolean,',
    '    val base: Color,',
    '    val glows: List<WallpaperGlow>,',
    ')',
    '',
    '/** A named set of a theme, an accent, and a wallpaper, applied together. */',
    'data class ThemePackToken(',
    '    val id: String,',
    '    val label: String,',
    '    val description: String,',
    '    val isLight: Boolean,',
    '    val accentId: String,',
    '    val wallpaperId: String,',
    ')',
    '',
  ].join('\n');
}
